from atcoder.dsu import DSU

N, Q = map(int, input().split())
uf = [DSU(N + 1) for i in range(10)]
ans = 10 * N - 10
for i in range(N - 1 + Q):
    a, b, c = map(int, input().split())
    for j in range(c, 10):
        if not uf[j].same(a, b):
            ans -= 1
            uf[j].merge(a, b)
    if i >= N - 1:
        print(ans)
